(6248553, 923785, 54446, '<td valign="top">This is a very good nature/landscape image with an unfortunate title.  No points off for the title, but it may weigh down your image.    I''m sure you didn''t mean anything profound, but it sure is a distraction.</td>', 'This is a very good nature/landscape image with an unfortunate title.  No points off for the title, but it may weigh down your image.    I''m sure you didn''t mean anything profound, but it sure is a distraction.', '2010-12-08 06:26:15.000000', NULL, 1),
(6248560, 924195, 54446, '<td valign="top">Beautiful portrait of this child.  The background is less than ideal.  It''s not terrible, but it distracts a little.  7</td>', 'Beautiful portrait of this child.  The background is less than ideal.  It''s not terrible, but it distracts a little.  7', '2010-12-08 06:28:34.000000', NULL, 1),
