(6254445, 924251, 96751, '<td valign="top">So many alternate subjects from everyone.  Never would have guessed this was you.  Spectacular image.  When did you move to Iceland, LOL!!</td>', 'So many alternate subjects from everyone.  Never would have guessed this was you.  Spectacular image.  When did you move to Iceland, LOL!!', '2010-12-15 01:56:05.000000', NULL, 0),
(6254446, 924245, 30982, '<td valign="top">Another top ten (I''m sure it doesn''t ever get old!), a good score, no 1''s and only one each of 2 and 3.  Mostly, though, an exceptionally nice portrait with to-die-for bokeh.  Nice!</td>', 'Another top ten (I''m sure it doesn''t ever get old!), a good score, no 1''s and only one each of 2 and 3.  Mostly, though, an exceptionally nice portrait with to-die-for bokeh.  Nice!', '2010-12-15 01:56:31.000000', NULL, 0),
