(6254448, 923864, 30982, '<td valign="top">Congrats!  Great catch!  Or are they fed?  Colors are marvelous.</td>', 'Congrats!  Great catch!  Or are they fed?  Colors are marvelous.', '2010-12-15 01:57:07.000000', NULL, 0),
(6254451, 923864, 96751, '<td valign="top">Congrats on a killer (no pun intended) image, Cory.  And on your first (I''m sure of many more) ribbon.</td>', 'Congrats on a killer (no pun intended) image, Cory.  And on your first (I''m sure of many more) ribbon.', '2010-12-15 01:57:51.000000', NULL, 0),
